import React, { useState, useEffect } from 'react';
import { Box, Typography, Paper, Button, CircularProgress } from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import StarsIcon from '@mui/icons-material/Stars';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { useNavigate } from 'react-router-dom';
import { observer } from "mobx-react-lite";

const AutoApproved = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 5000);
    return () => clearTimeout(timer);
  }, []);

  if (loading) {
    return (
      <Box sx={{ minHeight: '350px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', bgcolor: 'white', p: 4 }}>
        <CircularProgress size={60} thickness={4} sx={{ color: '#0F4977', mb: 2 }} />
        <Typography variant="h6" sx={{ color: '#0F4977', fontWeight: 600, mt: 2 }}>
          Processing Auto Approval...
        </Typography>
      </Box>
    );
  }

  return (
    <Box
      sx={{
        minHeight: '350px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        bgcolor: 'white',
        p: 4,
        gap: 2,
      }}
    >
      <Button
        startIcon={<ArrowBackIcon />}
        onClick={() => navigate(-1)}
        sx={{ alignSelf: 'flex-start', mb: 2, color: '#0F4977', fontWeight: 600 }}
        variant="text"
      >
        Back
      </Button>
      <Paper elevation={3} sx={{ p: 3, borderRadius: 3, bgcolor: '#EAF2F7', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
        <CheckCircleIcon sx={{ fontSize: 60, color: '#43A047' }} />
        <Typography variant="h5" sx={{ fontWeight: 700, color: '#0F4977', mb: 1 }}>
          Prior Authorization Auto-Approved
        </Typography>
        <Typography variant="subtitle1" sx={{ color: '#333', fontWeight: 500, textAlign: 'center' }}>
          Your medical service request has been automatically approved based on your provider's Gold Card status and predictive analytics.
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
          <StarsIcon sx={{ color: '#FB4E0B', fontSize: 32 }} />
          <Typography variant="body1" sx={{ fontWeight: 500, color: '#0F4977' }}>
            Service Type: {`Advanced Predictive Model`}
          </Typography>
        </Box>
        <Box sx={{ mt: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <EmojiEventsIcon sx={{ color: '#FFD700', fontSize: 32 }} />
          <Typography variant="body2" sx={{ color: '#666', textAlign: 'center' }}>
            No additional documentation or review is required. Your insurance provider has recognized your eligibility for expedited approval, ensuring timely access to care.
          </Typography>
        </Box>
        <Typography variant="body2" sx={{ color: '#0F4977', mt: 2, textAlign: 'center', fontWeight: 500 }}>
          If you have questions about your approval or next steps, please contact your insurance representative.
        </Typography>
      </Paper>
    </Box>
  );
};

export default observer(AutoApproved);
