import React, { useEffect, useState } from 'react';
import {
  Box,
  Typography,
  Button,
  Collapse,
  IconButton,
  Grid,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
} from '@mui/material';
import {
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  AttachFile as AttachFileIcon,
  Description as DescriptionIcon,
} from '@mui/icons-material';
import { observer } from 'mobx-react-lite';
import { useParams } from 'react-router-dom';

interface FileUpload {
  id: string;
  name: string;
  extension: string;
  size: string;
}


interface DecisionGuidanceProps {
  decisionGData: any;        
  clinicalEhrData: any;
}

const DecisionGuidance: React.FC<DecisionGuidanceProps> = ({ decisionGData,clinicalEhrData }) => {
  const { pa_status, procedure_name,patient_id } = useParams<{ pa_status?: string; procedure_name?: string,patient_id?:string }>();

  const [expandedSections, setExpandedSections] = useState<{
    [key: string]: boolean;
  }>({
    assessment: false,
    recommendations: false,
    summary:true,
  });
  
  const [supportingDocs, setSupportingDocs] = useState<FileUpload[]>([]);
  const [clinicalNotes, setClinicalNotes] = useState<FileUpload[]>([]);

  const toggleSection = (section: string) => {
    setExpandedSections((prev) => ({
      ...prev,
      [section]: !prev[section],
    }));
  };

  const handleFileUpload = (
    event: React.ChangeEvent<HTMLInputElement>,
    type: 'supporting' | 'clinical'
  ) => {
    const files = event.target.files;
    if (files) {
      const newFiles: FileUpload[] = Array.from(files).map((file) => {
        const extension = file.name.split('.').pop() || '';
        const sizeInKB = (file.size / 1024).toFixed(2);
        return {
          id: `${Date.now()}-${Math.random()}`,
          name: file.name,
          extension: extension.toUpperCase(),
          size: `${sizeInKB} KB`,
        };
      });

      if (type === 'supporting') {
        setSupportingDocs((prev) => [...prev, ...newFiles]);
      } else {
        setClinicalNotes((prev) => [...prev, ...newFiles]);
      }
    }
  };

  const removeFile = (id: string, type: 'supporting' | 'clinical') => {
    if (type === 'supporting') {
      setSupportingDocs((prev) => prev.filter((file) => file.id !== id));
    } else {
      setClinicalNotes((prev) => prev.filter((file) => file.id !== id));
    }
  };

  return (
    <Box sx={{ minHeight: '100vh', backgroundColor: '#fff' }}> 

      {/* Main Content */}
      <Box sx={{ 
        // maxWidth: 1200, 
        // margin: '0 auto', 
        p: 2 
        }}>
        {/* <Paper
          elevation={0}
          sx={{
            p: 3,
            backgroundColor: '#fff',
            borderRadius: 2,
            border: '1px solid #e0e0e0',
          }}
        > */}
<Box
  sx={{   
    boxSizing: 'border-box',
    border: '2px solid',          
    borderColor: '#EAF2F7',   
    borderRadius: 2,               
                     
  }}
>
        {/* Decision Guidance Header */}
             <Box
                  sx={{
                    bgcolor: '#EAF2F7',
                    p: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    borderBottom: '1px solid rgba(0,0,0,0.1)',
                  }}
                >
          <Typography
            sx={{
              fontSize: '0.875rem',
              color: '#666',
            //   mb: 2,
              fontWeight: 500,
            }}
          >
            Decision Guidance
          </Typography>
          </Box>

          <Box sx={{p:1}}>

          {/* Request Summary */}

           <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                cursor: 'pointer',
                // py: 1,
              }}
              onClick={() => toggleSection('summary')}
            >

          <Typography
            sx={{
              fontSize: '1rem',
              fontWeight: 600,
              color: '#000',
              mb: 2,
              mt:2,
            }}
          >
            Request Summary
          </Typography>
           <IconButton size="small">
                {expandedSections.summary ? (
                  <ExpandLessIcon />
                ) : (
                  <ExpandMoreIcon />
                )}
              </IconButton>
          </Box>
          <Collapse in={expandedSections.summary}>
          <Grid container spacing={2} sx={{ mb: 2,pl:2 }}>
            
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>

              <Box display='flex' flexDirection='row' gap={1}>
                <Typography
                  sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                >
                  Procedure
                </Typography>
                <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                  {procedure_name?.replace(/_/g, " ")}
                </Typography>
              </Box>
            </Box>
           
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>

              <Box display='flex' flexDirection='row' gap={3}>
                <Typography
                  sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                >
                  Patient
                </Typography>
                <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                  {clinicalEhrData[0]?.patient_name}
                </Typography>
              </Box>
            </Box>
            
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>

             <Box display='flex' flexDirection='row' gap={2}>
                <Typography
                  sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                >
                  Provider
                </Typography>
                <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                  {clinicalEhrData[0]?.demographics?.primary_care_provider}
                </Typography>
              </Box>
            </Box>
            
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>

               <Box display='flex' flexDirection='row' gap={3}>
                <Typography
                  sx={{ fontSize: '0.875rem', color: '#666'}}
                >
                  Facility
                </Typography>
                <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                {clinicalEhrData[0]?.pa_metadata?.requesting_provider?.facility}

                </Typography>
              </Box>
            </Box>
          </Grid>
          </Collapse>
          {/* <Divider sx={{ my: 3 }} /> */}

          {/* PA Assessment Details */}
          <Box sx={{ mb: 2 }}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                cursor: 'pointer',
                // py: 1,
              }}
              onClick={() => toggleSection('assessment')}
            >
              <Typography
                sx={{
                  fontSize: '1rem',
                  fontWeight: 600,
                  color: '#000',
                }}
              >
                CQL Assessment Details
              </Typography>
              <IconButton size="small">
                {expandedSections.assessment ? (
                  <ExpandLessIcon />
                ) : (
                  <ExpandMoreIcon />
                )}
              </IconButton>
            </Box>
            <Collapse in={expandedSections.assessment}>
              <Box sx={{ pl: 2, pt: 2 }}>
                <Grid container spacing={2}>
                 
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>
    <Box display='flex' flexDirection='row' gap={3}>

                    <Typography
                      sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                    >
                      Likelihood of Approval
                    </Typography>
                    <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                     {decisionGData?.likelihood_text}
                    </Typography>
                  </Box>
                </Box>  
<Box
  sx={{
    flexBasis: { xs: '100%', sm: '50%' }, // width equivalent to xs=12, sm=6
    maxWidth: { xs: '100%', sm: '50%' },  // ensures it doesn't exceed
    boxSizing: 'border-box',
  }}
>
               <Box display='flex' flexDirection='row' gap={6.5}>
                    <Typography
                      sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                    >
                      Confidence Score
                    </Typography>
                    <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                      {decisionGData?.confidence}
                    </Typography>
                </Box>

               <Box display='flex' flexDirection='row' gap={6.5}>
                  <Typography
                      sx={{ fontSize: '0.875rem', color: '#666', mb: 0.5 }}
                    >
                      Key Reasons
                    </Typography>
                    <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                      {decisionGData?.key_reasons}
                    </Typography>
                </Box>

                  </Box>
                </Grid>
              </Box>
            </Collapse>
          </Box>

          {/* <Divider sx={{ my: 2 }} /> */}

          {/* Recommendations */}
          <Box >
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                cursor: 'pointer',
                py: 1,
              }}
              onClick={() => toggleSection('recommendations')}
            >
              <Typography
                sx={{
                  fontSize: '1rem',
                  fontWeight: 600,
                  color: '#000',
                }}
              >
                Recommendations
              </Typography>
              <IconButton size="small">
                {expandedSections.recommendations ? (
                  <ExpandLessIcon />
                ) : (
                  <ExpandMoreIcon />
                )}
              </IconButton>
            </Box>
            <Collapse in={expandedSections.recommendations} sx={{pl:2}}>
              {/* <Box sx={{ pl: 2, pt: 2 }}>
                <Typography sx={{ fontSize: '0.875rem', color: '#000' }}>
                  No specific recommendations at this time.
                </Typography>
              </Box> */}
               <Box 
            //    sx={{ mb: 3 }}
               >
            <Typography
              sx={{
                fontSize: '0.875rem',
                color: '#1976d2',
                // mb: 1,
                fontWeight: 500,
                cursor: 'pointer',
                display: 'inline-flex',
                alignItems: 'center',
                // gap: 0.5,
                '&:hover': { textDecoration: 'underline' },
              }}
              component="label"
            >
              Attach supporting documents
              <input
                type="file"
                multiple
                hidden
                onChange={(e) => handleFileUpload(e, 'supporting')}
              />
            </Typography>

            {supportingDocs.length > 0 && (
              <List sx={{ mt: 2 }}>
                {supportingDocs.map((file) => (
                  <ListItem
                    key={file.id}
                    sx={{
                      backgroundColor: '#f5f5f5',
                      borderRadius: 1,
                      mb: 1,
                      border: '1px solid #e0e0e0',
                    }}
                    secondaryAction={
                      <Button
                        size="small"
                        onClick={() => removeFile(file.id, 'supporting')}
                        sx={{ minWidth: 'auto', color: '#666' }}
                      >
                        ×
                      </Button>
                    }
                  >
                    <ListItemIcon>
                      <DescriptionIcon sx={{ color: '#1976d2' }} />
                    </ListItemIcon>
                    <ListItemText
                      primary={file.name}
                      secondary={`${file.extension} • ${file.size}`}
                      primaryTypographyProps={{
                        fontSize: '0.875rem',
                        color: '#000',
                      }}
                      secondaryTypographyProps={{
                        fontSize: '0.75rem',
                        color: '#666',
                      }}
                    />
                  </ListItem>
                ))}
              </List>
            )}
          </Box>

          {/* Add Clinical Notes */}
          <Box sx={{ mb: 4 }}>
            <Typography
              sx={{
                fontSize: '0.875rem',
                color: '#1976d2',
                mb: 1,
                fontWeight: 500,
                cursor: 'pointer',
                display: 'inline-flex',
                alignItems: 'center',
                gap: 0.5,
                '&:hover': { textDecoration: 'underline' },
              }}
              component="label"
            >
              Add clinical notes
              <input
                type="file"
                multiple
                hidden
                onChange={(e) => handleFileUpload(e, 'clinical')}
              />
            </Typography>

            {clinicalNotes.length > 0 && (
              <List sx={{ mt: 2 }}>
                {clinicalNotes.map((file) => (
                  <ListItem
                    key={file.id}
                    sx={{
                      backgroundColor: '#f5f5f5',
                      borderRadius: 1,
                      mb: 1,
                      border: '1px solid #e0e0e0',
                    }}
                    secondaryAction={
                      <Button
                        size="small"
                        onClick={() => removeFile(file.id, 'clinical')}
                        sx={{ minWidth: 'auto', color: '#666' }}
                      >
                        ×
                      </Button>
                    }
                  >
                    <ListItemIcon>
                      <DescriptionIcon sx={{ color: '#1976d2' }} />
                    </ListItemIcon>
                    <ListItemText
                      primary={file.name}
                      secondary={`${file.extension} • ${file.size}`}
                      primaryTypographyProps={{
                        fontSize: '0.875rem',
                        color: '#000',
                      }}
                      secondaryTypographyProps={{
                        fontSize: '0.75rem',
                        color: '#666',
                      }}
                    />
                  </ListItem>
                ))}
              </List>
            )}
          </Box>
            </Collapse>
          </Box>

          {/* <Divider sx={{ my: 3 }} /> */}

         
         

          {/* Action Buttons */}
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'flex-end',
              gap: 2,
            //   pt: 2,
            }}
          >
            <Button
              variant="outlined"
              sx={{
                textTransform: 'none',
                color: '#666',
                borderColor: '#ccc',
                px: 3,
                '&:hover': {
                  borderColor: '#999',
                  backgroundColor: '#f5f5f5',
                },
              }}
            >
              Cancel
            </Button>
            <Button
              variant="contained"
              sx={{
                textTransform: 'none',
                backgroundColor: '#1e3a5f',
                px: 3,
                '&:hover': {
                  backgroundColor: '#152a47',
                },
              }}
            >
              Submit PA Request
            </Button>
          </Box>
         </Box>
         </Box>
        {/* </Paper> */}
      </Box>
    </Box>
  );
};

export default observer(DecisionGuidance);
