import React, { useState } from "react";
import { CircularProgress, Typography, Box, Button, Dialog, DialogTitle, IconButton, DialogContent } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import { useNavigate } from "react-router-dom";

interface DecisionGuidanceProps {
  isLoading: boolean;
  decisionGData: any;
  isDGsubmited: Boolean;
}


const formatKey = (key: string) => {
  return key
    .split("_")
    .map(word => word.charAt(0).toUpperCase() + word.slice(1)) // capitalize each word
    .join(" ");
};


const DecisionGuidanceDisplay: React.FC<DecisionGuidanceProps> = ({ isLoading, decisionGData, isDGsubmited }) => {
  const [openThanksDialog, setOpenThanksDialog] = useState(false);
  const navigate = useNavigate();


  if (isLoading) {
    return (
      <Box
        sx={{
          display: "flex",
          flexDirection: "column", 
          justifyContent: "center",
          alignItems: "center",
          height: "200px",
          fontSize: 12
        }}
      >
        <div>Processing Request ... Please wait</div>
        <CircularProgress sx={{ mt: 2 }} /> 
      </Box>
    );
  }

  if (!decisionGData && isDGsubmited) {
    return <Typography>No data available</Typography>;
  }

  return (
    <Box sx={{ p: 2, borderRadius: "8px" }}>
      {decisionGData && (
        <Typography sx={{ mb: 2, fontSize: 16, fontWeight: "bold" }}>
          Decision Guidance
        </Typography>
      )}
      {decisionGData && Object.entries(decisionGData)?.map(([key, value]) => (
        <Box key={key} sx={{ mb: 1 }}>
          <Typography sx={{ fontSize: 12, fontWeight: "bold" }}>
            {formatKey(key)}:
          </Typography>
          <Typography sx={{ fontSize: 12 }}>{String(value)}</Typography>
        </Box>
      ))}

      {/* Action Buttons */}
      {decisionGData && (
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 2,
          }}
        >
        <Button
          onClick={()=>{
            navigate('/pharmacy-portal/case-prep');
          }}
            variant="contained"
            sx={{
              textTransform: 'none',
              backgroundColor: '#f2780cff',
              px: 3,
              '&:hover': {
                backgroundColor: '#9c5a04ff',
              },
            }}
          >
           Case Prep
          </Button>

          <Button
          onClick={()=>{
            setOpenThanksDialog(true);
          }}
            variant="contained"
            sx={{
              textTransform: 'none',
              backgroundColor: '#1e3a5f',
              px: 3,
              '&:hover': {
                backgroundColor: '#152a47',
              },
            }}
          >
            Submit PA Request
          </Button>
        </Box>
      )}


      <Dialog open={openThanksDialog} onClose={() => setOpenThanksDialog(false)} fullWidth maxWidth="sm">
        <DialogTitle
          sx={{
            backgroundColor: "#F3FAFF",
            p: 0.3,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}
        >
          <Typography sx={{ fontWeight: 600, fontSize: 12 }}>
          </Typography>
          <IconButton onClick={() => setOpenThanksDialog(false)} size="small">
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        {/* Content */}
        <DialogContent
          sx={{
            mt: 1,
            pt: 0, // ✅ Removes top padding
            pb: 1, // Optional: reduce bottom padding
            px: 3  // Keep horizontal padding if needed
          }}
        >
          <Typography sx={{ fontWeight: "bold", fontSize: 12, mb: 1,textAlign:"center" }}>
            PA request is successfully submitted.
          </Typography>
        </DialogContent>
      </Dialog>


    </Box>
  );
};

export default DecisionGuidanceDisplay;