import React, { useEffect } from 'react';
import DecisionGuidance from '../components/DecisionGuidance/DecisionGuidance';
import { mainPageStore } from '../stores/MainPageStore';
import { observer } from 'mobx-react-lite';
import { useParams } from 'react-router-dom';

const DescisionGuidancePage = () => {
  const { fetchDecisionGuidanceData,fetchClinicalAssesmentData } = mainPageStore;
  const { pa_status, procedure_name,patient_id } = useParams<{ pa_status?: string; procedure_name?: string,patient_id?:string }>();

  useEffect(() => {
    if (pa_status && procedure_name) {
      fetchDecisionGuidanceData(pa_status, procedure_name);
    }
    if (patient_id && procedure_name) {
      fetchClinicalAssesmentData(patient_id, procedure_name);
    }
  }, [pa_status, procedure_name,patient_id ]);

  const rawDecisionGData = mainPageStore.decisionGuidanceData;
  const decisionGData = typeof rawDecisionGData === "string" ? JSON.parse(rawDecisionGData) : rawDecisionGData;
  const clinicalEhrData = mainPageStore.clinicalAssesmentEhrData;
  const currentPatient = clinicalEhrData?.slice(0, 2);

  return (
    <div style={{ backgroundColor: "#f5f5f5", minHeight: "100vh" }}>
      <DecisionGuidance decisionGData={decisionGData} clinicalEhrData={currentPatient} />
    </div>
  );
};


export default observer(DescisionGuidancePage);