import React from "react";
import { Page, Text, View, Document, StyleSheet } from "@react-pdf/renderer";
import { toJS } from "mobx";
import { useParams } from "react-router-dom";
import { mainPageStore } from '../../stores/MainPageStore';
import { observer } from "mobx-react-lite";

const styles = StyleSheet.create({
  page: {
    paddingTop: 50, 
    paddingHorizontal: 20,
    paddingBottom: 20,
    fontSize: 12
  },
  section: { marginBottom: 10 },
  heading: { fontSize: 14, fontWeight: "bold", marginBottom: 5 },
  topheading: { fontSize: 14, fontWeight: "bold", marginBottom: 5,textAlign:"center" },
  text: { marginBottom: 3,paddingTop: 3, },
  highlight: { backgroundColor: '#FFFF00', padding: 2 }

});

interface EHRPdfProps {
  ehrData: any[]; 
  patient_id:string;
}

const EHRPdf: React.FC<EHRPdfProps> = ({ ehrData,patient_id }) => {
  console.log('patient_id',patient_id);
  console.log('data',toJS(ehrData));

  const citation = mainPageStore.questionCitation;

  const filteredData  = ehrData?.filter((item:any) =>
            item?.member_id.toLowerCase().includes(patient_id?.toLowerCase())
          );
  console.log('data1',toJS(filteredData));

  return (
<Document>
      <Page size="A4" style={styles.page}>
        <Text style={styles.topheading}>EHR Data Report</Text>

        {filteredData.map((record, index) => (
          <View key={index} style={styles.section}>
            {/* Patient Info */}
            <Text style={styles.heading}>Patient: {String(record.patient_name)}</Text>
            <Text style={styles.text}>Member ID: {String(record.member_id)}</Text>
            <Text style={styles.text}>DOB: {String(record.demographics?.dob)}</Text>
            <Text style={styles.text}>Gender: {String(record.demographics?.gender)}</Text>
            <Text style={styles.text}>Insurance: {String(record.demographics?.insurance_plan)}</Text>
            <Text style={styles.text}>Primary Care: {String(record.demographics?.primary_care_provider)}</Text>

            {/* PA Metadata */}
            <Text style={styles.heading}>Prior Authorization:</Text>
            <Text style={styles.text}>Status: {String(record.pa_metadata?.status)}</Text>
            <Text style={styles.text}>Submission Date: {String(record.pa_metadata?.submission_date)}</Text>
            <Text style={styles.text}>Tracking ID: {String(record.pa_metadata?.tracking_id)}</Text>
            <Text style={styles.text}>Requesting Provider: {String(record.pa_metadata?.requesting_provider?.name)}</Text>

            {/* Citation Highlight */}
            {citation && (
              <>
                <Text style={styles.heading}>Citation:</Text>
                <Text style={[styles.text, styles.highlight]}>{String(citation)}</Text>
              </>
            )}

            {/* Health Profile */}
            <Text style={styles.heading}>Health Profile:</Text>
            {record.health_profile?.map((hp: any, i: number) => (
              <Text key={i} style={styles.text}>
                Diabetes: {hp.has_diabetes === '1' ? 'Yes' : 'No'}, Hypertension: {hp.has_hypertension === '1' ? 'Yes' : 'No'}, BMI: {String(hp.bmi)}
              </Text>
            ))}

            {/* Problem List */}
            <Text style={styles.heading}>Problem List:</Text>
            {record.problem_list?.map((problem: any, i: number) => (
              <Text key={i} style={styles.text}>- {String(problem)}</Text>
            ))}

            {/* Medications */}
            <Text style={styles.heading}>Medications:</Text>
            {record.medications?.map((med: any, i: number) => (
              <Text key={i} style={styles.text}>
                {String(med.name)} ({String(med.dose)}, {String(med.frequency)})
              </Text>
            ))}

            {/* Allergies */}
            {record.allergies?.length > 0 && (
              <>
                <Text style={styles.heading}>Allergies:</Text>
                {record.allergies.map((allergy: any, i: number) => (
                  <Text key={i} style={styles.text}>
                    {String(allergy.substance)} - {String(allergy.reaction)}
                  </Text>
                ))}
              </>
            )}

            {/* Labs */}
            <Text style={styles.heading}>Lab Results:</Text>
            {record.labs?.map((lab: any, i: number) => (
              <Text key={i} style={styles.text}>
                {String(lab.date)}: {String(lab.type)} = {String(lab.value)} ({String(lab.interpretation)})
              </Text>
            ))}

            {/* Imaging */}
            <Text style={styles.heading}>Imaging Results:</Text>
            {record.imaging_results?.map((img: any, i: number) => (
              <Text key={i} style={styles.text}>
                {String(img.date)}: {String(img.test_name)} - {String(img.result_summary)}
              </Text>
            ))}

            {/* Encounters */}
            <Text style={styles.heading}>Encounters:</Text>
            {record.encounters?.map((enc: any, i: number) => (
              <Text key={i} style={styles.text}>
                {String(enc.date)} ({String(enc.type)}) - {String(enc.provider)}: {String(enc.clinical_notes)}
              </Text>
            ))}
          </View>
        ))}
      </Page>
    </Document>

  );
};

export default observer(EHRPdf);