import { makeAutoObservable, runInAction, toJS } from "mobx";
import { API_BASE_URL } from "./config/config";



export class MainPageStore {
  data: any = null;
  loading: boolean = false;
  sidemenuloading: boolean = false;
  error: string | null = null;
  sidebarCollapsed: boolean = true;
  middleBarCollapsed: boolean = true;
  apiUrl: string = API_BASE_URL;
  sidebarData: any = null;
  activeTab: string = "";
  activeSidebarItem: string = "";
  middleBarItems: { icon?: React.ElementType; label: string; href: string }[] = [];
  middleBarHeading: string = "";

  //Prior Auth Related
  homeData: any = [];
  homeLoading: boolean = false;
  answerData: any = [];
  rowKey: string = '';
  answerLoading: boolean = false;
  clinicalAssLoading: boolean = false;
  clinicalAssesment: any = [];
  clinicalAssesmentEhrData: any =[];
  decisionGuidanceLoading = false;
  decisionGuidanceData :any =null;
  visitedClinicalAssesment: any = [];
  questionCitation: string = '';

  //Patient Data
  patientLoading:boolean=false;
  patientformData:any=null;

  constructor() {
    makeAutoObservable(this);
  }

  setSidebarCollapsed = () => {
    this.sidebarCollapsed = !this.sidebarCollapsed;
  }

  setMiddleBarCollapsed = () => {
    this.middleBarCollapsed = !this.middleBarCollapsed;
  }

  setMiddleBarItems = (items: { icon?: React.ElementType; label: string; href: string }[], heading: string) => {
    this.middleBarItems = items;
    this.middleBarHeading = heading;
    this.middleBarCollapsed = items.length === 0; // collapse if empty
  };

  clearMiddleBar = () => {
    this.middleBarItems = [];
    this.middleBarHeading = "";
    this.middleBarCollapsed = true;
  };

  setActiveTab = (id: string) => {
    this.activeTab = id;
  }
  setActiveSidebarItem = (id: string) => {
    this.activeSidebarItem = id;
  }

  setSubmittedQuestions = (visitQS: any[]) =>{
    this.visitedClinicalAssesment = visitQS;
  }

   setQuestionCitation = (citation:string) =>{
    this.questionCitation = citation;
  }

  //Prior auth api for store
  fetchPriorAuthHomeData = async () => {
    try {
      this.homeLoading = true;
      const res = await fetch(`${this.apiUrl}/landing_page_data`);
      if (!res.ok) throw new Error("Failed to fetch Prior Auth Data");
      const data = await res.json();
      runInAction(() => {
        this.homeLoading = false;
        this.homeData = data;
      });

    } catch (e: any) {
      runInAction(() => {
        this.error = e.message;
      });
    }
  };


  fetchClinicalAssessmentData = async (
    patientId: string,
    procedureName: string,
  ) => {
    try {
      this.answerLoading = true;
      const res = await fetch(`${this.apiUrl}/clinical_assesment_data?patient_id=${patientId}&procedure_name=${procedureName}`);
      if (!res.ok) throw new Error("Failed to fetch Clinical Assessment Data");
      const data = await res.json();
      runInAction(() => {
        this.answerLoading = false;
        this.answerData = data.answer.questionnaire_llm_response;
        this.rowKey = data.row_key;
      });

    } catch (e: any) {
      runInAction(() => {
        this.error = e.message;
      });
    }
  };

  fetchClinicalAssesmentData = async (patient_id: string, procedure_name: string) => {
    try {
      this.clinicalAssLoading = true;
      const res = await fetch(`${this.apiUrl}/clinical_assesment_data?patient_id=${patient_id}&procedure_name=${procedure_name}`);
      if (!res.ok) throw new Error("Failed to fetch Clinical Assesment Data");
      const data = await res.json();
      runInAction(() => {
        this.clinicalAssLoading = false;
        this.clinicalAssesment = data?.answer?.questionnaire_llm_response;
        this.clinicalAssesmentEhrData = data?.answer?.ehr_data;
      });
    } catch (e: any) {
      runInAction(() => {
        this.error = e.message;
      });
    }
  };


fetchClinicalAssesmentDataUsingPost = async (
  request_id: string,
  member_id: string,
  procedure: string
) => {
  try {
    this.clinicalAssLoading = true;
    const res = await fetch(`${this.apiUrl}/prior-auth/assess`, {
      method: "POST",
      headers: {
        "accept": "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        "request_id":request_id,
        "member_id":member_id,
        "procedure":procedure
      }),
    });

    if (!res.ok) throw new Error("Failed to fetch Clinical Assessment Data");

    const data = await res.json();

    runInAction(() => {
      this.clinicalAssLoading = false;
      this.clinicalAssesment = data?.agent_output?.questionnaire_llm_response;
      this.clinicalAssesmentEhrData = data?.agent_output?.ehr_data;
    });
  } catch (e: any) {
    runInAction(() => {
      this.error = e.message;
    });
  }
};

    fetchDecisionGuidanceData = async (pa_status: string, procedure_name: string) => {
    try {
      this.decisionGuidanceLoading = true;
      const res = await fetch(`${this.apiUrl}/decision_guidance_page?pa_status=${pa_status}&procedure=${procedure_name}`);
      if (!res.ok) throw new Error("Failed to fetch Decision Guidance Data");
      const data = await res.json();
      runInAction(() => {
        this.decisionGuidanceLoading = false;
        this.decisionGuidanceData = data;
      });
    } catch (e: any) {
      runInAction(() => {
        this.error = e.message;
      });
    }
  };


fetchPatientData = async (patient_id: string) => {
  try {
    runInAction(() => { this.patientLoading = true; });

    // ensure fetchPriorAuthHomeData resolves with data (if possible)
    await this.fetchPriorAuthHomeData();

    // don't throw based on homeLoading — just read data
    const patientData = this.homeData?.find(
      (item: any) => String(item["Member ID"] ?? "").trim() === String(patient_id ?? "").trim()
    );

    // log non-proxied snapshot for debugging
    console.log("FOUND patient (raw):", patientData);

    runInAction(() => {
      this.patientformData = patientData ?? null;
      this.patientLoading = false;
      this.error = null;
    });

    return patientData ?? null;
  } catch (err: any) {
    runInAction(() => {
      this.error = err?.message ?? String(err);
      this.patientLoading = false;
    });
    return null;
  }
};

}

export const mainPageStore = new MainPageStore();
