import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Chip,
  TablePagination,
} from '@mui/material';
import {
  ExpandMore,
  CheckCircle,
  Warning,
  LocalHospital

} from '@mui/icons-material';
import MonitorHeartIcon from '@mui/icons-material/MonitorHeart';
import { useNavigate } from 'react-router-dom';

