interface AuthorizationRequestTableProps {
  // data: AuthorizationRequest[];
  data: any[];
  page: number;
  rowsPerPage: number;
  onPageChange: (event: unknown, newPage: number) => void;
  onRowsPerPageChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
}

const AuthorizationRequestTable: React.FC<AuthorizationRequestTableProps> = ({
  data,
  page,
  rowsPerPage,
  onPageChange,
  onRowsPerPageChange,
}) => {

  const navigate = useNavigate();

  const getStatusChip = (status: string) => {
    if (status === 'success') {
      return (
        <Chip
          icon={<CheckCircle sx={{ fontSize: '16px !important' }} />}
          label="Success"
          sx={{
            backgroundColor: '#d4edda',
            color: '#155724',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
            '& .MuiChip-icon': {
              color: '#28a745',
            },
          }}
        />
      );
      // } else if (status.includes('Pending')) {
    } else if (status.includes('pending review')) {
      return (
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
            <Warning sx={{ color: '#f0ad4e', fontSize: '18px' }} />
            <Typography
              sx={{
                fontFamily: 'Roboto, sans-serif',
                fontSize: '14px',
                color: '#856404',
              }}
            >
              Pending - In RN review
            </Typography>
          </Box>
        </Box>
      );
    } else if (status === 'approved') {
      return (
        <Chip
          icon={<CheckCircle sx={{ fontSize: '16px !important' }} />}
          label="Approved"
          sx={{
            backgroundColor: '#d4edda',
            color: '#155724',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
            '& .MuiChip-icon': {
              color: '#28a745',
            },
          }}
        />
      );
    } else if (status === 'denied') {
      return (
        <Chip
          label="Denied"
          sx={{
            backgroundColor: '#f8d7da',
            color: '#721c24',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
          }}
        />
      );
    } else if (status === 'draft') {
      return (
        <Chip
          label="Draft"
          sx={{
            backgroundColor: '#e2e3e5',
            color: '#383d41',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
          }}
        />
      );
    } else if (status === 'withdrawn') {
      return (
        <Chip
          label="Withdrawn"
          sx={{
            backgroundColor: '#fff3cd',
            color: '#856404',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
          }}
        />
      );
    } else if (status === 'completed') {
      return (
        <Chip
          icon={<CheckCircle sx={{ fontSize: '16px !important' }} />}
          label="Completed"
          sx={{
            backgroundColor: '#d1ecf1',
            color: '#0c5460',
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
            height: '28px',
            '& .MuiChip-icon': {
              color: '#17a2b8',
            },
          }}
        />
      );
    }
    return null;
  };

  // Paginate data
  const paginatedData = data.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );


  const calculateRange = (givenDate: string) => {
    const date = new Date(givenDate);

    // Start date: 19 days before
    const startDate = new Date(date);
    startDate.setDate(startDate.getDate() - 19);

    // End date: 1 month and 8 days after
    const endDate = new Date(date);
    endDate.setMonth(endDate.getMonth() + 1);
    endDate.setDate(endDate.getDate() + 8);

    const formatDate = (d: Date) =>
      `${d.getMonth() + 1}/${d.getDate()}/${d.getFullYear()}`;

    return `${formatDate(startDate)} - ${formatDate(endDate)}`;
  };



  function ParagraphSplitter(text: string) {


    // Split by comma and trim spaces
    if (!text) return null;
    const items = text.split(",").map(item => item.trim()).filter(Boolean);

    // Group into chunks of 4
    const chunks: string[] = [];
    // for (let i = 0; i < items.length; i += 4) {
    for (let i = 0; i < 1; i += 4) {
      let chunk = items.slice(i, i + 4).join(", ");
      // Append ellipsis if there are more items after this chunk
      if (i + 4 < items.length) {
        chunk += ' ...';
      }
      chunks.push(chunk);
    }

    return (
      <>
        {chunks.map((chunk, index) => (
          <div key={index}>{chunk}</div>
        ))}
      </>
    );
  }




  return (
    <Paper
      sx={{
        backgroundColor: 'white',
        border: '1px solid #e4e4e5',
        borderRadius: '8px',
        overflow: 'hidden',
      }}
      elevation={0}
    >
      {/* Header */}
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '16px',
          borderBottom: '1px solid #e4e4e5',
        }}
      >
        <Typography
          sx={{
            fontFamily: 'Roboto, sans-serif',
            fontSize: '16px',
            color: 'black',
          }}
        >
          Authorization Request Table
        </Typography>
        <ExpandMore
          sx={{
            fontSize: '18px',
            color: 'black',
          }}
        />
      </Box>

      {/* Table Content - All rows expanded by default */}
      <Box>
        {paginatedData.map((row, index) => (
          <Box key={row['SNO']}>
            <Box
              sx={{
                padding: '16px',
                backgroundColor: index % 2 === 0 ? 'white' : '#fafafa',
                borderBottom: '1px solid #e4e4e5',
              }}
            >
              {/* Row Header with Name and Details */}
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  marginBottom: '12px',
                }}
              >
                <Typography
                  sx={{
                    fontFamily: "Roboto, sans-serif",
                    fontSize: "16px",
                    color: "black",
                    cursor: "pointer",
                  }}
                  onClick={() => navigate(`/pharmacy-portal/new/pdf-viewer/${row["Member ID"]}/${row["Procedure Short Name"]}`)}

                >
                  {row["Patient Name"]}
                </Typography>

                <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center', flexWrap: 'wrap' }}>
                  <Box
                    sx={{
                      display: 'flex',
                      gap: '8px',
                      alignItems: 'flex-end',
                    }}
                  >
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'rgba(0,0,0,0.3)',
                      }}
                    >
                      DOB
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '16px',
                        color: 'black',
                      }}
                    >
                      {/* {row.dob} */}
                      {new Date(row.DOB).toLocaleDateString()}
                    </Typography>
                  </Box>

                  <Box
                    sx={{
                      display: 'flex',
                      gap: '8px',
                      alignItems: 'flex-end',
                    }}
                  >
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'rgba(0,0,0,0.3)',
                      }}
                    >
                      Member ID
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '16px',
                        color: 'black',
                      }}
                    >
                      {row["Member ID"]}
                    </Typography>
                  </Box>

                  <Box
                    sx={{
                      display: 'flex',
                      gap: '8px',
                      alignItems: 'flex-end',
                    }}
                  >
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'rgba(0,0,0,0.3)',
                      }}
                    >
                      Health Plan
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '16px',
                        color: 'black',
                      }}
                    >
                      {/* {row.healthPlan} */}
                      Health Plan
                    </Typography>
                  </Box>
                </Box>
              </Box>

              {/* Expanded Content - Always visible */}
              <Box sx={{ paddingTop: '8px' }}>
                {/* Service Info */}
                <Box
                  sx={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    gap: '10px',
                    marginBottom: '16px',
                  }}
                >
                  <Box
                    sx={{
                      backgroundColor: '#EAF2F7',
                      borderRadius: '12px',
                      padding: '10px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      width: '44px',
                      height: '44px',
                      flexShrink: 0,
                    }}
                  >
                    <MonitorHeartIcon
                      sx={{ color: '#0F4977', fontSize: '24px' }}
                    />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '12px',
                        color: 'rgba(0,0,0,0.3)',
                        marginBottom: '4px',
                      }}
                    >
                      Service
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'black',
                      }}
                    >
                      {/* {row.service} */}
                      {row[`Procedure Requested`]}
                    </Typography>
                  </Box>
                  <Box>{getStatusChip(row.Status.toLowerCase())}</Box>
                </Box>

                {/* Additional Details */}
                <Box
                  sx={{
                    display: 'flex',
                    gap: '24px',
                    paddingLeft: { xs: '0', sm: '54px' },
                    flexWrap: 'wrap',
                  }}
                >
                  <Box sx={{ minWidth: '150px' }}>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '12px',
                        color: 'rgba(0,0,0,0.3)',
                        marginBottom: '4px',
                      }}
                    >
                      Procedure
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'black',
                      }}
                    >
                      {/* {row.procedure} */}
                      {ParagraphSplitter(row["CPT / HCPCS Codes"])}
                    </Typography>
                  </Box>

                  <Box sx={{ minWidth: '150px' }}>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '12px',
                        color: 'rgba(0,0,0,0.3)',
                        marginBottom: '4px',
                      }}
                    >
                      Submission date
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'black',
                      }}
                    >
                      {/* {row.submissionDate} */}
                      {new Date(row["Submission Date"]).toLocaleDateString()}
                    </Typography>
                  </Box>

                  <Box sx={{ minWidth: '150px' }}>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '12px',
                        color: 'rgba(0,0,0,0.3)',
                        marginBottom: '4px',
                      }}
                    >
                      Date of service
                    </Typography>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: 'black',
                      }}
                    >
                      {/* {row.dateOfService} */}
                      {calculateRange(new Date(row["Submission Date"]).toLocaleDateString())}
                    </Typography>
                  </Box>
                </Box>

                {/* Tracking ID */}
                {row["Tracking ID"] && (
                  <Box sx={{ paddingLeft: { xs: '0', sm: '54px' }, marginTop: '8px' }}>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto, sans-serif',
                        fontSize: '14px',
                        color: '#856404',
                      }}
                    >
                      {/* Tracking {row.trackingId} */}
                      Tracking: {row["Tracking ID"]}
                    </Typography>
                  </Box>
                )}
              </Box>
            </Box>
          </Box>
        ))}
      </Box>

      {/* Pagination */}
      <TablePagination
        component="div"
        count={data.length}
        page={page}
        onPageChange={onPageChange}
        rowsPerPage={rowsPerPage}
        onRowsPerPageChange={onRowsPerPageChange}
        rowsPerPageOptions={[5, 10, 25]}
        sx={{
          borderTop: '1px solid #e4e4e5',
          '& .MuiTablePagination-selectLabel, & .MuiTablePagination-displayedRows':
          {
            fontFamily: 'Roboto, sans-serif',
            fontSize: '14px',
          },
        }}
      />
    </Paper>
  );
};

export default AuthorizationRequestTable;
