import React, { useEffect, useState } from "react";
import {
  Box,
  Typography,
  RadioGroup,
  FormControlLabel,
  Radio,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Button,
  IconButton,
  CircularProgress,
  LinearProgress
} from "@mui/material";
import {
  ExpandMore as ExpandMoreIcon,
  CheckCircle as CheckCircleIcon,
} from '@mui/icons-material';
import CheckIcon from '@mui/icons-material/Check';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import { mainPageStore } from '../../stores/MainPageStore';

import { useNavigate, useParams } from "react-router-dom";
import { toJS } from "mobx";
import { observer } from "mobx-react-lite";
import DecisionGuidanceDisplay from "../DecisionGuidance/DecisionGuidanceDisplay";

type Question = {
  q_id: string;
  answer: string;
  confidence_score: number;
  citation: string;
  ai_rationale: string;
  procedure: string;
  question: string;
  type: string;
  options: string;
  route_map: string;
  is_start: boolean;
  userAnswer?: string;
};

const ClinicalQuestion = () => {
  const { patient_id, procedure_name } = useParams<{ patient_id?: string; procedure_name?: string }>();
  const { fetchDecisionGuidanceData } = mainPageStore;
  const navigate = useNavigate();
  const initialQuestions: Question[] = mainPageStore.clinicalAssesment;
  const [openDialog, setOpenDialog] = useState(false);
  const [reason, setReason] = useState("");
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQId, setCurrentQId] = useState<string | null>("Q1");
  const [currentIndex, setCurrentIndex] = useState(1);
  const [visitedQuestions, setVisitedQuestions] = useState<Question[]>([]);
  const [isSubmit, setIsSubmit] = useState(false);
  const [finalOutcome, setFinalOutcome] = useState<string>("approve"); // default state
  const [isLoading, setIsLoading] = useState(false);
  const [isDGsubmited, setIsDGsubmited] = useState(false);


  const currentQuestion: Question | undefined = questions?.find(q => q.q_id === currentQId);
  useEffect(() => {
    if (initialQuestions && initialQuestions.length > 0) {
      setQuestions(initialQuestions);
      const firstQuestion = initialQuestions[0];
      if (firstQuestion) {
        setVisitedQuestions([firstQuestion]);
        setCurrentQId(firstQuestion.q_id);
      }
    }
  }, [initialQuestions]);

  console.log('currentQuestion', toJS(visitedQuestions));
  // const handleNext = () => {
  //   if (!currentQuestion) return;
  //   const routeMap = JSON.parse(currentQuestion.route_map.replace(/'/g, '"'));
  //   const nextQId = routeMap[currentQuestion.answer];
  //   console.log('nextQId',nextQId);
  //   if (nextQId && nextQId.startsWith("Q") && nextQId.length > 1) {
  //     const nextQuestion = initialQuestions.find(q => q.q_id === nextQId);
  //     if (nextQuestion) {
  //       setVisitedQuestions(prev => [...prev, nextQuestion]);
  //       setCurrentQId(nextQId);
  //       setCurrentIndex(currentIndex + 1);
  //     }
  //   }
  //   else {
  //     setIsSubmit(true);
  //     if (nextQId) {
  //       const [status] = nextQId.split(":"); // e.g. "APPROVE", "DENY", "NEED_INFO"
  //       setFinalOutcome(status?.toLowerCase() ?? "approve");
  //     } else {
  //       setFinalOutcome("approve"); // explicit default if nothing found
  //     }
  //   }
  // };


const handleNext = () => {
  if (!currentQuestion) return;

  // Parse route_map safely
  let routeMap: Record<string, string> = {};
  try {
    routeMap = JSON.parse(currentQuestion.route_map.replace(/'/g, '"'));
  } catch (err) {
    console.error("Invalid route_map format", err);
    return;
  }

  const nextQId = routeMap[currentQuestion.answer];
  console.log("nextQId", nextQId);

  if (nextQId && nextQId.startsWith("Q")) {
    const nextQuestion = questions.find(q => q.q_id === nextQId);
    if (nextQuestion) {
      setVisitedQuestions(prev => {
        // Avoid duplicates
        const alreadyVisited = prev.some(q => q.q_id === nextQId);
        return alreadyVisited ? prev : [...prev, nextQuestion];
      });
      setCurrentQId(nextQId);
      setCurrentIndex(prev => prev + 1); 
    }
  } else {
    // End of questionnaire
    setIsSubmit(true);
    if (nextQId) {
      const [status] = nextQId.split(":"); // e.g., "APPROVE"
      setFinalOutcome(status?.toLowerCase() ?? "approve");
    } else {
      setFinalOutcome("approve");
    }
  }
};

  // const handleCancel = () => {
  //   const firstQuestion = initialQuestions.find((q: Question) => q.q_id === "Q1");
  //   if (firstQuestion) {
  //     setVisitedQuestions([firstQuestion]); // Reset to only first question
  //     setCurrentQId("Q1");
  //     setCurrentIndex(1);
  //     setIsSubmit(false);
  //   }
  // };

  const handleCancel = () => {
  const firstQuestion = initialQuestions.find((q: Question) => q.q_id === "Q1");
  if (firstQuestion) {
    setVisitedQuestions([firstQuestion]); // Reset visited questions
    //setQuestions(initialQuestions.map(q => ({ ...q, answer: "" }))); //  Clear all answers
    setQuestions(initialQuestions);
    setCurrentQId("Q1"); // Reset current question
    setCurrentIndex(1); // Reset index
    setIsSubmit(false); // Reset submit state
    setFinalOutcome(""); //  Clear final outcome if you use it
    setOpenDialog(false); //  Close any open dialog
  }
};

  // const handleSubmit = () => {
  //   mainPageStore.setSubmittedQuestions(visitedQuestions);
  //   navigate(`/pharmacy-portal/summary/${finalOutcome}/${procedure_name}/${patient_id}`);
  // }


const handleSubmit = async () => {
  if (!currentQuestion) return;
  
  const finalProcedure = procedure_name || "Continuous_Glucose_Monitor";
  const finalStatus = finalOutcome || "approve";
  try {
    setIsLoading(true);
    setIsDGsubmited(true);
    await fetchDecisionGuidanceData(finalStatus, finalProcedure);
    console.log("Submitted:", { finalStatus, finalProcedure });
  } catch (error) {
    console.error("Error during submission:", error);
  } finally {
     setTimeout(() => {
      setIsLoading(false);
      setIsDGsubmited(false);
    }, 5000); // 5000 ms = 5 seconds
  }
};


const rawDecisionGData = mainPageStore?.decisionGuidanceData;
const decisionGData = typeof rawDecisionGData === "string" ? JSON.parse(rawDecisionGData) : rawDecisionGData;
console.log("Decision Guidance:", decisionGData)

  const handleClickCitation = (newCitation: string) => {
    mainPageStore.questionCitation = newCitation;
  }

  const totalQuestions = questions.length;
  const attempted = visitedQuestions.length;
//  const progress = totalQuestions > 0 ? (attempted / totalQuestions) * 100 : 0;
  const progress = isSubmit
  ? 100
  : totalQuestions > 0
    ? (attempted / totalQuestions) * 100
    : 0;


  return (
    <Box sx={{ display: "flex", flexDirection: "column", height: "100%" }}>
      {/* Heading Section */}
     <Box
  sx={{
    width: "100%",
    backgroundColor: "#f5f5f5",
    p: 1,
    borderBottom: "1px solid #ddd"
  }}
>
  {/* Header title */}
  <Typography sx={{ fontSize: 14, fontWeight: 600, mb: 1 }}>
    Clinical Question Set
  </Typography>

  {/* Progress bar inside the same container */}
  <Typography variant="body2" gutterBottom>
    Progress: {attempted} / {totalQuestions}
  </Typography>
  <LinearProgress variant="determinate" value={progress} 
    sx={{ width: "100%", height: 10, borderRadius: 5 }} 
  />
</Box>
     
      {mainPageStore.clinicalAssLoading ? (
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            alignItems: 'center',
            height: 200
          }}
        >
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <Typography variant="body2" sx={{ mr: 1 }}>
              Loading clinical question set...
            </Typography>
          </Box>
          <CircularProgress />
        </Box>
      ) : (
        <>
          {initialQuestions && initialQuestions.length > 0 ? (
            <Box sx={{ display: "flex", flex: 1 }}>
              {/* Sidebar */}

              <Box
                sx={{
                  width: "60px",
                  display: "flex",
                  flexDirection: "column",
                  gap: 2,
                  backgroundColor: "#f0f0f0",
                  p: 2,
                }}
              >
                {visitedQuestions?.map((q: Question, idx: number) => (
                  <Box
                    key={q.q_id}
                    sx={{
                      width: 30,
                      height: 30,
                      borderRadius: "50%",
                      border: "1px solid #ccc",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      backgroundColor: idx === currentIndex - 1 ? "#1976d2" : "#bebebeff",
                      color: "#fff",
                      fontWeight: 500,
                      fontSize: 12,
                      cursor: "pointer",
                    }}
                  >
                    {/* {q.q_id} */}
                    {idx + 1}
                  </Box>
                ))}
              </Box>
              {/* Main Content */}
              <Box sx={{ flex: 1, ml: 1, mt: 1 }}>
                {visitedQuestions?.map((q: Question, idx: number) => (
                  <Box key={q.q_id} sx={{ mb: 3, borderBottom: "1px solid #ddd", pb: 2 }}>
                    {/* Question Text */}
                    <Typography sx={{ fontSize: 12, fontWeight: "bold", mb: 2 }}>
                      {idx + 1}. {q.question}
                    </Typography>

                    {/* AI Suggested */}
                    {/* <Typography variant="subtitle2" sx={{ mb: 1, fontSize: 11 }}>
                      AI Suggested
                    </Typography> */}

                    {/* Options */}

                    <RadioGroup
                      value={q.answer || ""}
                      // onChange={(e) => {
                      //   setOpenDialog(true);
                      //   setVisitedQuestions(prev =>
                      //     prev.map(item =>
                      //       item.q_id === q.q_id ? { ...item, answer: e.target.value } : item
                      //     )
                      //   );
                      // }}
                      onChange={(e) => {
                            const value = e.target.value;
                            setOpenDialog(true);
                            setVisitedQuestions(prev =>
                              prev.map(item =>
                                item.q_id === q.q_id ? { ...item, answer: value } : item
                              )
                            );
                            setQuestions(prev =>
                              prev.map(item =>
                                item.q_id === q.q_id ? { ...item, answer: value } : item
                              )
                            );
                          }}
                      sx={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 0.5 }}
                    >
                      {JSON.parse(q.options.replace(/'/g, '"')).map((opt: string) => (
                        <FormControlLabel
                          key={opt}
                          value={opt}
                          control={<Radio sx={{ p: 0.5 }} />}
                          label={<Typography sx={{ fontSize: 12 }}>{opt}</Typography>}
                          sx={{ m: 0 }}
                          disabled={q.q_id !== currentQId}
                        />
                      ))}
                    </RadioGroup>
                    {/* CQL Assessment Details */}
                    <Accordion
                      sx={{
                        mt: 3,
                        mr: 0.5,
                        boxShadow: "none",
                        border: "1px solid rgba(0, 0, 0, 0.12)",
                        "&:before": { display: "none" },
                      }}
                    >
                      <AccordionSummary
                        expandIcon={<ExpandMoreIcon />}
                        sx={{
                          bgcolor: "rgba(177, 221, 250, 0.2)",
                          minHeight: "32px !important",
                          paddingY: "4px",
                        }}
                      >
                        <Box
                          sx={{
                            width: 20,
                            height: 20,
                            borderRadius: "2px",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                          }}
                        >
                          <CheckIcon sx={{ bgcolor: "#4CAF50", color: "#fff", fontSize: 16 }} />
                        </Box>
                        <Typography sx={{ fontWeight: 600, fontSize: 12, ml: 0.5 }}>
                          CQL Assessment Details
                        </Typography>
                      </AccordionSummary>
                      <AccordionDetails>
                        <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
                          {/* <Box sx={{ display: "flex", justifyContent: "space-between" }}>
                            <Typography sx={{ fontSize: 12 }}>
                              <strong>Confidence Score:</strong> {q.confidence_score}
                            </Typography>
                          </Box> */}
                          <Box>
                            <Typography sx={{
                              fontSize: 12, color: "black",
                              cursor: "pointer",
                            }}
                              onClick={() => handleClickCitation(q.citation)}
                            >
                              <strong>Citation:</strong> {q.citation}
                            </Typography>
                          </Box>
                          {/* <Box>
                            <Typography sx={{ fontSize: 12 }}>
                              <strong>AI Rationale:</strong> {q.ai_rationale}{" "}
                            </Typography>
                          </Box> */}
                        </Box>
                      </AccordionDetails>
                    </Accordion>
                  </Box>
                ))}

                {/* Buttons */}

             {!decisionGData && (
                <Box sx={{ display: "flex", justifyContent: "flex-end", mt: 3, gap: 2, mr: 2, mb: 2 }}>
                  <Button variant="outlined" onClick={handleCancel}>Cancel</Button>
                  {!isSubmit ? (
                    <Button variant="contained" sx={{ fontSize: 12 }} onClick={handleNext}>
                      Next
                    </Button>
                  ) : (
                    <Button
                      variant="contained"
                      sx={{ fontSize: 12, backgroundColor: "#4CAF50", "&:hover": { backgroundColor: "#45a049" } }}
                      //   onClick={() => {
                      //   console.log("Submit clicked", questions);
                      //   navigate(`/pharmacy-portal/summary`);
                      // }}
                      onClick={handleSubmit}
                    >
                      Decision guidance
                    </Button>
                  )}
                </Box>
               )}

                <DecisionGuidanceDisplay isLoading={isLoading} decisionGData={decisionGData} isDGsubmited={isDGsubmited}/>
              </Box>
            </Box>
          ) : (
            <Box sx={{ textAlign: "center", mt: 2 }}>
              <Typography sx={{ fontSize: 12 }}>No Clinical question set found.</Typography>
            </Box>
          )}

        </>
      )}

      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} fullWidth maxWidth="sm">
        {/* Heading */}
        <DialogTitle
          sx={{
            backgroundColor: "#F3FAFF",
            p: 0.3,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}
        >
          <Typography sx={{ fontWeight: 600, fontSize: 12 }}>
            Request to update answer prefilled by CQL Query Language
          </Typography>
          <IconButton onClick={() => setOpenDialog(false)} size="small">
            <CloseIcon />
          </IconButton>
        </DialogTitle>

        {/* Content */}
        <DialogContent
          sx={{
            mt: 1,
            pt: 0, // ✅ Removes top padding
            pb: 1, // Optional: reduce bottom padding
            px: 3  // Keep horizontal padding if needed
          }}
        >
          <Typography sx={{ fontWeight: "bold", fontSize: 12, mb: 1 }}>
            To help us understand your perspective, please share:
          </Typography>
          <Typography sx={{ fontSize: 12, mb: 2 }}>
            Why do you want to change the answer? (
            <span style={{ color: "#999999" }}>
              Please do share the reference if you have like pageno etc..
            </span>
            )
          </Typography>

          {/* Textarea */}
          <TextField
            multiline
            rows={2}
            fullWidth
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Write your explanation.."
            sx={{ mb: 0 }}
          />
        </DialogContent>

        {/* Actions */}
        <DialogActions sx={{ p: 1 }}>
          <Button variant="outlined" onClick={() => setOpenDialog(false)}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={() => {
              console.log("Reason saved:", reason);
              setOpenDialog(false);
            }}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>


    </Box>
  );
}

export default observer(ClinicalQuestion);