import React, { useState, useEffect } from 'react';
import { Box, Typography, Paper, Button, CircularProgress } from '@mui/material';
import VerifiedUserIcon from '@mui/icons-material/VerifiedUser';
import ThumbUpAltIcon from '@mui/icons-material/ThumbUpAlt';
import EmojiEmotionsIcon from '@mui/icons-material/EmojiEmotions';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { useNavigate } from 'react-router-dom';

const NoPriorAuthRequired = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 5000);
    return () => clearTimeout(timer);
  }, []);

  if (loading) {
    return (
      <Box sx={{ minHeight: '350px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', bgcolor: 'white', p: 4 }}>
        <CircularProgress size={60} thickness={4} sx={{ color: '#1B5E20', mb: 2 }} />
        <Typography variant="h6" sx={{ color: '#1B5E20', fontWeight: 600, mt: 2 }}>
          Checking Authorization Status...
        </Typography>
      </Box>
    );
  }

  return (
    <Box
      sx={{
        minHeight: '350px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        bgcolor: 'white',
        p: 4,
        gap: 2,
      }}
    >
      <Button
        startIcon={<ArrowBackIcon />}
        onClick={() => navigate(-1)}
        sx={{ alignSelf: 'flex-start', mb: 2, color: '#1B5E20', fontWeight: 600 }}
        variant="text"
      >
        Back
      </Button>
      <Paper elevation={3} sx={{ p: 3, borderRadius: 3, bgcolor: '#EAF7EA', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
        <VerifiedUserIcon sx={{ fontSize: 60, color: '#43A047' }} />
        <Typography variant="h5" sx={{ fontWeight: 700, color: '#1B5E20', mb: 1 }}>
          No Prior Authorization Required
        </Typography>
        <Typography variant="subtitle1" sx={{ color: '#333', fontWeight: 500, textAlign: 'center' }}>
          Based on your insurance plan and service type, prior authorization is not needed for this medical request.
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
          <ThumbUpAltIcon sx={{ color: '#FB4E0B', fontSize: 32 }} />
          <Typography variant="body1" sx={{ fontWeight: 500, color: '#1B5E20' }}>
            Fast Track Service: Immediate Access
          </Typography>
        </Box>
        <Box sx={{ mt: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <EmojiEmotionsIcon sx={{ color: '#FFD700', fontSize: 32 }} />
          <Typography variant="body2" sx={{ color: '#666', textAlign: 'center' }}>
            You can proceed directly to care - no extra paperwork or delays. Your insurance provider has confirmed eligibility for streamlined approval.
          </Typography>
        </Box>
        <Typography variant="body2" sx={{ color: '#1B5E20', mt: 2, textAlign: 'center', fontWeight: 500 }}>
          For questions about your coverage or next steps, please contact your insurance representative.
        </Typography>
      </Paper>
    </Box>
  );
};

export default NoPriorAuthRequired;
